import math

import pytest


def fact(n: int) -> int:
    """Return the factorial of a non-negative integer n.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    return math.factorial(n)


def test_fact_zero() -> None:
    assert fact(0) == 1


def test_fact_positive() -> None:
    assert fact(1) == 1
    assert fact(2) == 2
    assert fact(3) == 6
    assert fact(5) == 120
    assert fact(7) == 5040


def test_fact_negative() -> None:
    with pytest.raises(ValueError):
        fact(-1)

